# 使用列表实现队列数据结构
class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, item):
        self.items.append(item)

    def dequeue(self):
        if not self.is_empty():
            return self.items.pop(0)
        return None

    def front(self):
        if not self.is_empty():
            return self.items[0]
        return None

    def is_empty(self):
        return len(self.items) == 0

    def size(self):
        return len(self.items)

# 测试队列操作
queue = Queue()
queue.enqueue("客户A")
queue.enqueue("客户B")
queue.enqueue("客户C")
print(f"队首: {queue.front()}")
print(f"服务: {queue.dequeue()}")
print(f"队列大小: {queue.size()}")
